() => {
  const out = [];
  const cards = document.querySelectorAll('li.cl-search-result, li.result-row');
  cards.forEach(c => {
    const a = c.querySelector('a.cl-app-anchor, a.result-title, a');
    const t = (c.innerText || '').split('\n').slice(0,3).join(' | ').slice(0,160);
    if (a && a.href) out.push({title: t, href: a.href});
  });
  return JSON.stringify(out.slice(0, 40));
}
